# Property-assignment form on purpose: the "New-Object System.IO.Ports.SerialPort $port,$baud,..."
# positional form silently failed inside background jobs once (see docs/06 P-08), which led to a
# false "device is dead" conclusion. Keep this form.
param(
    [string]$Port = "COM9",
    [int]$Baud = 1000000,
    [int]$Seconds = 90,
    [string]$Out = "evidence\M3\bench_serial_2026-10-17.log"
)

$ErrorActionPreference = "Stop"

$dir = Split-Path -Parent $Out
if ($dir -and -not (Test-Path $dir)) {
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
}

$sp = New-Object System.IO.Ports.SerialPort
$sp.PortName  = $Port
$sp.BaudRate  = $Baud
$sp.Parity    = [System.IO.Ports.Parity]::None
$sp.DataBits  = 8
$sp.StopBits  = [System.IO.Ports.StopBits]::One
$sp.ReadTimeout = 500
$sp.NewLine   = "`n"
$sp.DtrEnable = $false
$sp.RtsEnable = $false

$lines = 0
try {
    $sp.Open()
    Write-Host "[capture] opened $Port @ $Baud, writing to $Out, ${Seconds}s"
    $sw = New-Object System.IO.StreamWriter($Out, $false, (New-Object System.Text.UTF8Encoding($false)))
    $deadline = (Get-Date).AddSeconds($Seconds)
    while ((Get-Date) -lt $deadline) {
        try {
            $line = $sp.ReadLine()
            if ($null -ne $line) {
                $sw.WriteLine($line.TrimEnd("`r"))
                $sw.Flush()
                $lines++
            }
        } catch [System.TimeoutException] {
        }
    }
    $sw.Close()
} finally {
    if ($sp.IsOpen) { $sp.Close() }
    $sp.Dispose()
}
Write-Host "[capture] done, $lines lines"
