$deadline = (Get-Date).AddSeconds($Seconds)
$reconnects = 0
while ((Get-Date) -lt $deadline) {
    try {
        # A USB re-plug invalidates the old handle, so reopen whenever we find it closed.
        if (-not $sp.IsOpen) {
            $sp.Open()
            $reconnects++
            Write-Host "[capture] (re)opened $Port (times=$reconnects)"
        }
        $line = $sp.ReadLine()
        if ($null -ne $line) {
            $sw.WriteLine($line.TrimEnd("`r"))
            $sw.Flush()
            $lines++
        }
    } catch [System.TimeoutException] {
    } catch {
        Write-Host "[capture] port error: $($_.Exception.Message)"
        try { if ($sp.IsOpen) { $sp.Close() } } catch { }
        Start-Sleep -Milliseconds 300
    }
}

