               (unsigned)st.perfect, (unsigned)st.good, (unsigned)st.miss,
               (unsigned)st.score, (unsigned)(st.acc_x100 / 100), (unsigned)(st.acc_x100 % 100));

    judge_init();   /* 不留测试状态 */
    return (int)bad;
}
