void gfx_text(int x, int y, const char *s, uint16_t color, int scale)
{
    int w, h;
    uint16_t *buf;
    int cx = x;

    if (!s || scale < 1)
        return;

    if (scale > 4)
        scale = 4;

    buf = g_buf(&w, &h);
    if (!buf)
        return;

    for (; *s; s++)
    {
        unsigned char c = (unsigned char)*s;
        const uint8_t *glyph;

        if (c >= 'a' && c <= 'z')
            c = (unsigned char)(c - 'a' + 'A');

        glyph = (c >= 0x20 && c <= 0x5A) ? s_font5x7[c - 0x20] : s_font5x7[0];

        for (int col = 0; col < 5; col++)
        {
            uint8_t bits = glyph[col];

            if (!bits)
                continue;

            for (int row = 0; row < 7; row++)
            {
                if (!(bits & (1u << row)))
                    continue;

                /* scale 放大：一个点写成 scale×scale 的方块 */
                for (int dy = 0; dy < scale; dy++)
                {
                    int py = y + row * scale + dy;
                    if (py < 0 || py >= h)
                        continue;
                    uint16_t *line = buf + (rt_uint32_t)py * (rt_uint32_t)w;
                    for (int dx = 0; dx < scale; dx++)
                    {
                        int px = cx + col * scale + dx;
                        if (px >= 0 && px < w)
                            line[px] = color;
                    }
                }
            }
        }

        cx += 6 * scale;   /* 5 列字形 + 1 列字距 */
    }
}

int gfx_text_width(const char *s, int scale)
{
    int n = 0;

    if (!s || scale < 1)
        return 0;

    while (*s++)
        n++;

    return n ? (n * 6 - 1) * scale : 0;
}
```

`scale` 上限 4 是防止误用画出巨大字。

