static int parse_uint(const char *p, const char *end, uint32_t *out)
{
    uint32_t v = 0;
    int got = 0;

    while (p < end && *p >= '0' && *p <= '9')
    {
        if (v > 100000000u)     /* 溢出保护 */
            return -1;
        v = v * 10u + (uint32_t)(*p - '0');
        p++;
        got = 1;
    }

    if (!got)
        return -1;

    *out = v;
    return (int)(p - ...);  /* 返回消耗的字符数 */
}
```

用指针返回更方便：

```c
static int parse_uint(const char **pp, const char *end, uint32_t *out)
{
    const char *p = *pp;
    uint32_t v = 0;
    int got = 0;

    while (p < end && *p >= '0' && *p <= '9')
    {
        v = v * 10u + (uint32_t)(*p - '0');
        if (v > 100000000u)
            return -1;
        p++;
        got = 1;
    }

    if (!got)
        return -1;

    *pp = p;
    *out = v;
    return 0;
}
```

