```c
int chart_parse(const char *text, int len)
{
    const char *p, *end;
    int line = 0;
    uint32_t n = 0, prev_ms = 0;
    int have_prev = 0;

    s_info.notes = 0;   /* 解析失败时保证 info 无效 */

    if (!text)
        return -1;

    p = text;
    end = (len < 0) ? (text + strlen(text)) : (text + len);

    while (p < end)
    {
        const char *eol = p;
        const char *q;

        while (eol < end && *eol != '\n' && *eol != '\r')
            eol++;

        line++;

        /* 跳过行首空白 */
        q = p;
        while (q < eol && (*q == ' ' || *q == '\t'))
            q++;

        if (q < eol && *q != '#')       /* 非空且非纯注释行 */
        {
            uint32_t t_ms = 0, lane = 0;

            if (parse_uint(&q, eol, &t_ms) != 0)
                return -line;

            if (q >= eol || (*q != ' ' && *q != '\t'))
                return -line;

            while (q < eol && (*q == ' ' || *q == '\t'))
                q++;

            if (parse_uint(&q, eol, &lane) != 0)
                return -line;

            while (q < eol && (*q == ' ' || *q == '\t'))
                q++;

            if (q < eol && *q != '#')   /* 轨号后只能是空白或注释 */
                return -line;

            if (t_ms > CHART_MAX_MS)
                return -line;
            if (lane > 3u)
                return -line;
            if (have_prev && t_ms < prev_ms)
                return -line;
            if (n >= JUDGE_MAX_NOTES)
                return -line;

            s_notes[n].hit_ms = t_ms;
            s_notes[n].lane = (uint8_t)lane;
            s_notes[n].state = 0;
            n++;
            prev_ms = t_ms;
            have_prev = 1;
        }

        /* 前进到下一行 */
        p = eol;
        if (p < end && *p == '\r')
            p++;
        if (p < end && *p == '\n')
            p++;
    }

    /* 填摘要 */
    memset(&s_info, 0, sizeof(s_info));
    s_info.notes = n;
    if (n > 0)
    {
        s_info.first_ms = s_notes[0].hit_ms;
        s_info.last_ms = s_notes[n - 1].hit_ms;
        for (uint32_t i = 0; i < n; i++)
            s_info.per_lane[s_notes[i].lane]++;
    }

    return (int)n;
}
