void scene_update(uint32_t now_ms)
{
    struct touch_ev ev;
    int w = fb_width();
    int lane_w = (w > 0) ? (w / LANE_COUNT) : 1;

    if (lane_w < 1)
        lane_w = 1;

    /* 事件分派：只有本线程 pop 队列（单消费者，见 docs/02 §4.2） */
    while (touch_pop_event(&ev) == 0)
    {
        if (s_scene == SCENE_TITLE || s_scene == SCENE_RESULT)
        {
            enter_playing(now_ms);
        }
        else if (s_scene == SCENE_PLAYING)
        {
            int lane = (int)ev.x / lane_w;

            if (lane >= LANE_COUNT)
                lane = LANE_COUNT - 1;
            if (lane < 0)
                lane = 0;

            /* 用谱面时间判定，与 note.hit_ms 同一坐标系 */
            enum judge_result r = judge_touch((uint8_t)lane, s_chart_ms);

            if (r != JUDGE_NONE)
                rt_kprintf("[HIT] lane=%d tap=%ums chart=%ums -> %s\n",
                           lane, (unsigned)ev.t_ms, (unsigned)s_chart_ms,
                           judge_result_name(r));
        }
    }

    if (s_scene == SCENE_PLAYING)
    {
        struct judge_stat st;

        s_chart_ms = now_ms - s_play_start_ms;
        judge_tick(s_chart_ms);
        judge_stats(&st);

        if (chart_note_count() > 0 && st.judged >= chart_note_count())
            enter_result(now_ms);
    }
    else if (s_scene == SCENE_RESULT)
    {
        if (now_ms - s_result_ms >= RESULT_TIMEOUT_MS)
            enter_title();
    }
}
