#include "app.h"
#include <string.h>

/*
 * TC-007 的「错误谱面时对应项显示 FAIL」演示开关：
 *   0 = 正常启动（默认）
 *   1 = 用一份故意错误的谱面当内置谱面，第 1 节应输出 FAIL
 */
#ifndef SELFTEST_INJECT_BAD_CHART
#define SELFTEST_INJECT_BAD_CHART   0
#endif

/* 故意错误的谱面：第 2 行轨号 9 越界，解析应返回 -2 */
