    "1500 9\n";

static int s_early_fail;

/* 第 1 节：谱面解析（REQ-006） */
static int section_chart(void)
{
    int fail = 0;
    int bad, good;

    rt_kprintf("\n--- [SELFTEST] 第 1 节：谱面解析（REQ-006）---\n");

    /*
     * 错误谱面必须先测：chart_parse 失败会把内部状态置为无效，
