            rt_kprintf("  内置谱面摘要: FAIL（期望 58 音符 / 末 29500ms）\n");
            fail++;
        }
    }
    else
    {
        rt_kprintf("  内置谱面: FAIL（返回 %d）\n", good);
        fail++;
    }

    return fail;
}
